import{c as t,Q as s,j as n,m as e}from"./chunks/framework.DOi4mjdC.js";const A=JSON.parse('{"title":"SetAtomicAdd","description":"","frontmatter":{},"headers":[{"level":1,"title":"SetAtomicAdd","slug":"setatomicadd"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/原子操作/SetAtomicAdd.md","filePath":"api/SIMD-API/基础API/原子操作/SetAtomicAdd.md"}'),l={name:"api/SIMD-API/基础API/原子操作/SetAtomicAdd.md"};function i(p,a,d,o,c,r){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="setatomicadd" tabindex="-1">SetAtomicAdd <a class="header-anchor" href="#setatomicadd" aria-label="Permalink to &quot;SetAtomicAdd&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>调用该接口后，可对后续的从VECOUT/L0C/L1到GM的数据传输开启原子累加，通过模板参数设定不同的累加数据类型。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void SetAtomicAdd()</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>设定不同的累加数据类型。 Atlas 训练系列产品，支持的数据类型为：float；支持的数据通路为VECOUT-&gt;GM。 Atlas 推理系列产品AI Core，支持的数据类型为int16_t/half/float；支持的数据通路为VECOUT-&gt;GM。 Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为int8_t/int16_t/half/bfloat16_t/int32_t/float；支持的数据通路为VECOUT/L0C/L1-&gt;GM。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为int8_t/int16_t/half/bfloat16_t/int32_t/float；支持的数据通路为VECOUT/L0C/L1-&gt;GM。 Ascend 950PR/Ascend 950DT，支持的数据类型为int8_t/int16_t/half/bfloat16_t/int32_t/float；支持的数据通路为VECOUT/L0C Buffer-&gt;GM。 Atlas 200I/500 A2 推理产品，支持的数据类型为int16_t/half/int32_t/float；支持的数据通路为VECOUT/L0C/L1-&gt;GM</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>累加操作完成后，建议通过<a href="./DisableDmaAtomic.html">DisableDmaAtomic</a>关闭原子累加，以免影响后续相关指令功能。</li><li>该指令执行前不会对GM的数据做清零操作，开发者根据实际的算子逻辑判断是否需要清零，如果需要自行进行清零操作。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>本示例中，使用DataCopy从VECOUT搬出数据到外部dstGlobal时进行原子累加。为保证原子累加的正确性，在核函数调用前，需要对dstGm清零。详细示例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/03_basic_api/08_atomic_operations/data_movement_with_atomic_operations" target="_blank" rel="noreferrer">DataMovementWithAtomicOperations样例</a>。</p><p>调用示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>constexpr uint32_t SIZE = 256;</span></span>
<span class="line"><span>__aicore__ inline void CopyIn()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::LocalTensor&lt;T&gt; srcLocal = queueSrc.AllocTensor&lt;T&gt;();</span></span>
<span class="line"><span>    // 清空原子操作的状态</span></span>
<span class="line"><span>    AscendC::DisableDmaAtomic();</span></span>
<span class="line"><span>    AscendC::DataCopy(srcLocal, srcGlobal, SIZE);</span></span>
<span class="line"><span>    queueSrc.EnQue(srcLocal);</span></span>
<span class="line"><span>    // 核间同步</span></span>
<span class="line"><span>    AscendC::SyncAll();</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>__aicore__ inline void CopyOut()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::LocalTensor&lt;T&gt; srcLocal = queueSrc.DeQue&lt;T&gt;();</span></span>
<span class="line"><span>    // 开启原子累加模式，3个核并行累加</span></span>
<span class="line"><span>    AscendC::SetAtomicAdd&lt;T&gt;();</span></span>
<span class="line"><span>    AscendC::DataCopy(dstGlobal, srcLocal, SIZE);</span></span>
<span class="line"><span>    // 关闭原子操作</span></span>
<span class="line"><span>    AscendC::DisableDmaAtomic();</span></span>
<span class="line"><span>    queueSrc.FreeTensor(srcLocal);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每个核的输入数据Src0: [1,1,1,1,1,...,1] // 256个1</span></span>
<span class="line"><span>输出数据初始值dstGm：[2,2,2,2,2,...,2] // dstGm初始值设置为2</span></span>
<span class="line"><span>最终输出数据dstGm: [5,5,5,5,5,...,5] // 256个5，3个核累加</span></span></code></pre></div>`,20)])])}const m=t(l,[["render",i]]);export{A as __pageData,m as default};
